cannibalism_unregister_current_country_actor = {
	set_temp_variable = { cannibalism_actor_unregister_result = 0 }
	if = {
		limit = {
			is_in_array = { array = global.cannibalism_actor_countries value = THIS }
			cannibalism_current_actor_generation_matches = yes
		}
		remove_from_array = { array = global.cannibalism_actor_countries value = THIS }
		clr_country_flag = cannibalism_country_active
		set_country_flag = cannibalism_country_cleanup_complete
		set_temp_variable = { cannibalism_report_callback_quarantine_days = constant:cannibalism_timing.presentation_delay_days }
		add_to_temp_variable = { cannibalism_report_callback_quarantine_days = constant:cannibalism_timing.pulse_flag_buffer_days }
		set_country_flag = { flag = cannibalism_report_callback_quarantine days = cannibalism_report_callback_quarantine_days }
		clear_variable = cannibalism_actor_generation
		set_temp_variable = { cannibalism_actor_unregister_result = 1 }
	}
}

cannibalism_register_current_state_node = {
	if = {
		limit = {
			has_event_target = cannibalism_node_source_actor
			event_target:cannibalism_node_source_actor = {
				exists = yes
				has_variable = cannibalism_actor_generation
				is_cannibalism_active_country = yes
			}
			NOT = { has_state_flag = cannibalism_active_node }
			NOT = { is_in_array = { array = global.cannibalism_node_states value = THIS } }
		}
		add_to_variable = { global.cannibalism_next_node_id = 1 }
		add_to_variable = { global.cannibalism_next_node_generation = 1 }
		set_variable = { cannibalism_node_id = global.cannibalism_next_node_id }
		set_variable = { cannibalism_node_generation = global.cannibalism_next_node_generation }
		set_variable = { cannibalism_node_type = cannibalism_new_node_type }
		set_variable = { cannibalism_node_strength = cannibalism_new_node_strength }
		set_variable = { cannibalism_node_source_country = event_target:cannibalism_node_source_actor }
		set_variable = { cannibalism_node_source_country_generation = event_target:cannibalism_node_source_actor.cannibalism_actor_generation }
		set_state_flag = cannibalism_active_node
		add_to_array = { array = global.cannibalism_node_states value = THIS }
		set_temp_variable = { cannibalism_new_state_stage = cannibalism_new_node_stage }
		cannibalism_set_current_state_stage = yes
	}
}

cannibalism_retire_current_state_node = {
	set_temp_variable = { cannibalism_node_retire_result = 0 }
	if = {
		limit = {
			is_in_array = { array = global.cannibalism_node_states value = THIS }
			cannibalism_current_node_identity_matches = yes
		}
		remove_from_array = { array = global.cannibalism_node_states value = THIS }
		clr_state_flag = cannibalism_active_node
		clear_variable = cannibalism_node_id
		clear_variable = cannibalism_node_generation
		clear_variable = cannibalism_node_type
		clear_variable = cannibalism_node_strength
		clear_variable = cannibalism_node_source_country
		clear_variable = cannibalism_node_source_country_generation
		clr_state_flag = cannibalism_external_route_node
		clear_variable = cannibalism_external_route_type
		set_temp_variable = { cannibalism_node_retire_result = 1 }
	}

cannibalism_retire_current_pulse_callback = {
	set_temp_variable = { cannibalism_pulse_callback_retire_result = 0 }
	set_temp_variable = { cannibalism_rehome_pulse_immediate = 0 }
	if = {
		limit = { cannibalism_current_country_owns_active_pulse_callback = yes }
		set_temp_variable = { cannibalism_rehome_pulse_days = global.cannibalism_pulse_due_date }
		subtract_from_temp_variable = { cannibalism_rehome_pulse_days = global.date }
		if = {
			limit = { check_variable = { cannibalism_rehome_pulse_days < 1 } }
			set_temp_variable = { cannibalism_rehome_pulse_immediate = 1 }
		}
		set_variable = { cannibalism_retired_pulse_ticket = cannibalism_scheduled_pulse_ticket }
		set_country_flag = cannibalism_retired_pulse_callback
		clear_variable = cannibalism_scheduled_pulse_ticket
		clr_country_flag = cannibalism_pulse_scheduled
		clr_country_flag = cannibalism_pulse_anchor
		clear_variable = global.cannibalism_active_pulse_ticket
		clear_variable = global.cannibalism_pulse_due_date
		clear_global_event_target = cannibalism_pulse_anchor
		set_temp_variable = { cannibalism_pulse_callback_retire_result = 1 }
	}
}

cannibalism_rehome_current_pulse_callback = {
	cannibalism_retire_current_pulse_callback = yes
	if = {
		limit = { check_variable = { cannibalism_pulse_callback_retire_result > 0 } }
		cannibalism_find_replacement_pulse_anchor = yes
		if = {
			limit = {
				check_variable = { cannibalism_replacement_anchor_found < 1 }
				has_event_target = cannibalism_lifecycle_successor
			}
			event_target:cannibalism_lifecycle_successor = {
				if = {
					limit = {
						exists = yes
						NOT = { has_capitulated = yes }
						NOT = { is_actual_nonhuman_country = yes }
						NOT = { is_cannibalism_reusable_warlord_slot_country = yes }
						NOT = { has_country_flag = cannibalism_retired_pulse_callback }
					}
					set_country_flag = cannibalism_recovery_coordinator
					cannibalism_select_current_country_as_pulse_anchor = yes
					set_temp_variable = { cannibalism_replacement_anchor_found = 1 }
				}
			}
		}
		if = {
			limit = {
				check_variable = { cannibalism_replacement_anchor_found > 0 }
				has_event_target = cannibalism_pulse_anchor
			}
			event_target:cannibalism_pulse_anchor = {
				if = {
					limit = { check_variable = { cannibalism_rehome_pulse_immediate > 0 } }
					cannibalism_run_pulse_on_valid_anchor = yes
				}
				else = {
					set_temp_variable = { cannibalism_next_pulse_days = cannibalism_rehome_pulse_days }
					cannibalism_schedule_current_pulse_after_delay = yes
				}
			}
		}

cannibalism_process_current_node_pulse = {
	if = {
		limit = {
			has_state_flag = cannibalism_active_node
			has_variable = cannibalism_node_id
			has_variable = cannibalism_node_generation
			OR = {
				NOT = { has_variable = cannibalism_last_processed_pulse_sequence }
				check_variable = {
					var = cannibalism_last_processed_pulse_sequence
					value = global.cannibalism_pulse_sequence
					compare = less_than
				}
			}
		}
		set_variable = { cannibalism_last_processed_pulse_sequence = global.cannibalism_pulse_sequence }
		set_temp_variable = { cannibalism_node_pulse_delta = 0 }
		set_temp_variable = { cannibalism_node_source_is_live = 0 }

		if = {
			limit = {
				has_variable = cannibalism_node_source_country
				has_variable = cannibalism_node_source_country_generation
				country_exists = var:cannibalism_node_source_country
			}
			set_temp_variable = { cannibalism_expected_source_generation = cannibalism_node_source_country_generation }
			var:cannibalism_node_source_country = {
				if = {
					limit = {
						is_cannibalism_active_country = yes
						check_variable = {
							var = cannibalism_actor_generation
							value = cannibalism_expected_source_generation
							compare = equals
						}
					}
					set_temp_variable = { cannibalism_node_source_is_live = 1 }
				}
			}
		}
		if = {
			limit = { check_variable = { cannibalism_node_source_is_live > 0 } }
			add_to_temp_variable = { cannibalism_node_pulse_delta = constant:cannibalism_delta.weekly_node_growth }
		}
		if = {
			limit = { cannibalism_state_is_isolated = yes }
			add_to_temp_variable = { cannibalism_node_pulse_delta = constant:cannibalism_delta.weekly_network_node }
		}
		if = {
			limit = {
				CONTROLLER = {
					is_cannibalism_active_ordinary_country = yes
					check_variable = {
						var = cannibalism_command_integrity
						value = constant:cannibalism_meter.active
						compare = greater_than_or_equals
					}
				}
			}
			add_to_temp_variable = { cannibalism_node_pulse_delta = constant:cannibalism_delta.weekly_node_suppression }
		}
		add_to_variable = { cannibalism_node_strength = cannibalism_node_pulse_delta }
		clamp_variable = { var = cannibalism_node_strength min = constant:cannibalism_meter.min max = constant:cannibalism_meter.max }

		if = {
			limit = {
				check_variable = {
					var = cannibalism_node_strength
					value = constant:cannibalism_meter.dormant
					compare = less_than_or_equals
				}
			}
			cannibalism_mark_current_state_for_recovery = yes

clear_array = cannibalism_warlord_harvested_countries
set_variable = { cannibalism_warlord_major_victory_count = 0 }
clr_country_flag = cannibalism_warlord_slot_release_verified
clr_country_flag = cannibalism_warlord_slot_release_pending
clr_country_flag = cannibalism_warlord_integration_release_pending
clear_variable = cannibalism_warlord_slot_reuse_date
set_variable = { cannibalism_warlord_origin = cannibalism_selected_warlord_origin }
set_variable = { cannibalism_warlord_region = cannibalism_selected_warlord_region }
set_variable = { cannibalism_warlord_origin_state = event_target:cannibalism_warlord_origin_state }
if = {
	limit = { has_event_target = cannibalism_warlord_former_owner }
	set_variable = { cannibalism_warlord_former_owner = event_target:cannibalism_warlord_former_owner }
}
add_to_variable = { global.cannibalism_next_warlord_generation = 1 }
set_variable = { cannibalism_warlord_slot_generation = global.cannibalism_next_warlord_generation }
set_variable = { global.cannibalism_warlord_slot_generation_entries^cannibalism_warlord_slot_index = cannibalism_warlord_slot_generation }
set_variable = { global.cannibalism_warlord_slot_reuse_date_entries^cannibalism_warlord_slot_index = 0 }

set_stability = constant:cannibalism_warlord_creation.starting_stability
set_war_support = constant:cannibalism_warlord_creation.starting_war_support
set_research_slots = constant:cannibalism_warlord_creation.starting_research_slots

cannibalism_resolve_forensic_recovery = {
	if = {
		limit = { cannibalism_can_pay_forensics_cost = yes }
		cannibalism_pay_forensics_cost = yes
		cannibalism_expose_detention_exploitation_in_current_country = yes
		set_temp_variable = { cannibalism_forensics_full_weight = constant:cannibalism_decision_result.forensics_full_weight }
		set_temp_variable = { cannibalism_forensics_partial_weight = constant:cannibalism_decision_result.forensics_partial_weight }
		set_temp_variable = { cannibalism_forensics_failure_weight = constant:cannibalism_decision_result.forensics_failure_weight }
		if = {
			limit = { has_country_flag = cannibalism_policy_open_emergency }
			add_to_temp_variable = { cannibalism_forensics_full_weight = constant:cannibalism_decision_result.forensics_open_bonus }
		}
		if = {
			limit = { has_country_flag = cannibalism_policy_concealment }
			add_to_temp_variable = { cannibalism_forensics_failure_weight = constant:cannibalism_decision_result.forensics_concealment_failure_bonus }
		}
		random_list = {
			cannibalism_forensics_full_weight = {
				add_to_variable = { cannibalism_evidence = constant:cannibalism_decision_result.forensics_full_evidence }
				add_to_variable = { cannibalism_cell_strength = constant:cannibalism_decision_result.forensics_full_cell }
				set_country_flag = cannibalism_forensic_site_secured
			}
			cannibalism_forensics_partial_weight = {
				add_to_variable = { cannibalism_evidence = constant:cannibalism_decision_result.forensics_partial_evidence }
				add_to_variable = { cannibalism_cell_strength = constant:cannibalism_decision_result.forensics_partial_cell }
				set_country_flag = cannibalism_forensic_partial_recovery
			}
			cannibalism_forensics_failure_weight = {
				add_to_variable = { cannibalism_command_integrity = constant:cannibalism_decision_result.forensics_failure_integrity }
				add_to_variable = { cannibalism_cell_strength = constant:cannibalism_decision_result.forensics_failure_cell }
				set_country_flag = cannibalism_forensic_team_compromised
			}
		}
		cannibalism_clamp_current_country_evidence = yes
		cannibalism_clamp_current_country_meters = yes
		cannibalism_refresh_country_penalty_variables = yes
		cannibalism_record_investigation_operation = yes
	}

