cannibalism_find_expected_spread_row_for_screening = {
	set_temp_variable = { cannibalism_expected_spread_row_found = 0 }
	set_temp_variable = { cannibalism_screening_requested_spread_id = cannibalism_expected_spread_id }
	cannibalism_validate_spread_queue = yes
	set_temp_variable = { cannibalism_expected_spread_id = cannibalism_screening_requested_spread_id }
	if = {
		limit = {
			check_variable = { cannibalism_spread_queue_validation_result > 0 }
			check_variable = { cannibalism_screening_requested_spread_id > 0 }
			has_event_target = cannibalism_screening_state
		}
		set_temp_variable = { cannibalism_spread_queue_index = 0 }
		while_loop_effect = {
			limit = {
				check_variable = {
					var = cannibalism_spread_queue_index
					value = global.cannibalism_spread_queue_status_entries^num
					compare = less_than
				}
			}
			if = {
				limit = {
					cannibalism_loaded_spread_status_is_live = yes
					check_variable = {
						var = global.cannibalism_spread_queue_id_entries^cannibalism_spread_queue_index
						value = cannibalism_screening_requested_spread_id
						compare = equals
					}
					var:global.cannibalism_spread_queue_target_state_entries^cannibalism_spread_queue_index = {
						state = event_target:cannibalism_screening_state
					}
				}
				set_temp_variable = { cannibalism_expected_spread_row_found = 1 }
			}
			add_to_temp_variable = { cannibalism_spread_queue_index = 1 }
		}
	}
}

