		}
		set_temp_variable = { cannibalism_spread_cost_manpower = constant:cannibalism_spread.humane_screening_manpower }
		multiply_temp_variable = { cannibalism_spread_cost_manpower = -1 }
		add_manpower = cannibalism_spread_cost_manpower
		set_temp_variable = { cannibalism_spread_cost_support = constant:cannibalism_spread.humane_screening_support }
		multiply_temp_variable = { cannibalism_spread_cost_support = -1 }
		add_equipment_to_stockpile = { type = support_equipment_1 amount = cannibalism_spread_cost_support producer = ROOT }
		set_temp_variable = { cannibalism_spread_cost_command = constant:cannibalism_spread.humane_screening_command }
		multiply_temp_variable = { cannibalism_spread_cost_command = -1 }
		add_command_power = cannibalism_spread_cost_command
		add_stability = constant:cannibalism_spread.humane_screening_stability
		event_target:cannibalism_screening_state = {
